function update(dt) {
  // ship movement
  if (keys.ArrowLeft) ship.x -= ship.speed;
  if (keys.ArrowRight) ship.x += ship.speed;
  if (keys.ArrowUp) ship.y -= ship.speed;
  if (keys.ArrowDown) ship.y += ship.speed;
  // keep within bounds
  ship.x = Math.max(0, Math.min(width - ship.w, ship.x));
  ship.y = Math.max(0, Math.min(height - ship.h, ship.y));

  // spawn asteroids
  if (performance.now() - lastSpawn > spawnInterval) {
    spawnAsteroid();
    lastSpawn = performance.now();
  }

  // move asteroids
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx;
    a.y += a.vy;
    // remove off-screen
    if (a.y - a.r > height) asteroids.splice(i, 1);
    // collision
    if (rectCircleCollide(ship, a)) gameOver = true;
  }

  // update stars (scroll down for parallax effect)
  for (let i = stars.length - 1; i >= 0; i--) {
    const s = stars[i];
    s.y += 0.5; // slow drift
    if (s.y > height) {
      s.y = 0;
      s.x = Math.random() * width;
    }
    // occasional twinkle
    if (Math.random() < 0.01) s.bright = !s.bright;
  }
}

